import { test, expect } from '@playwright/test';

test.describe('Add and Remove Product from Cart', () => {
  test.beforeEach(async ({ page }) => {
    await page.goto('https://www.saucedemo.com');
  });

  test('should successfully add and remove a product from the cart', async ({ page }) => {
    // Login with standard user
    const usernameInput = page.getByLabel('Username');
    const passwordInput = page.getByLabel('Password');
    const loginButton = page.getByRole('button', { name: 'Login' });

    await usernameInput.fill('standard_user');
    await passwordInput.fill('secret_sauce');
    await loginButton.click();

    // Verify login success
    await expect(page.getByRole('heading', { name: 'Products' })).toBeVisible();

    // Add product to cart
    const backpackButton = page.getByTestId('add-to-cart-sauce-labs-backpack');
    await backpackButton.click();

    // Verify cart badge shows 1
    const cartBadge = page.locator('.shopping_cart_badge');
    await expect(cartBadge).toHaveText('1');

    // Verify button label changes to 'Remove'
    await expect(backpackButton).toHaveText('Remove');

    // Remove product from cart
    await backpackButton.click();

    // Verify cart badge is empty
    await expect(cartBadge).toHaveText('0');

    // Verify button label changes back to 'Add to Cart'
    await expect(backpackButton).toHaveText('Add to Cart');
  });

  test('should handle multiple items in cart and remove them individually', async ({ page }) => {
    // Login with standard user
    const usernameInput = page.getByLabel('Username');
    const passwordInput = page.getByLabel('Password');
    const loginButton = page.getByRole('button', { name: 'Login' });

    await usernameInput.fill('standard_user');
    await passwordInput.fill('secret_sauce');
    await loginButton.click();

    // Add first product
    const backpackButton = page.getByTestId('add-to-cart-sauce-labs-backpack');
    await backpackButton.click();

    // Verify cart badge shows 1
    const cartBadge = page.locator('.shopping_cart_badge');
    await expect(cartBadge).toHaveText('1');

    // Add second product
    const phoneButton = page.getByTestId('add-to-cart-sauce-labs-phone');
    await phoneButton.click();

    // Verify cart badge shows 2
    await expect(cartBadge).toHaveText('2');

    // Remove first product
    await backpackButton.click();

    // Verify cart badge shows 1
    await expect(cartBadge).toHaveText('1');

    // Verify backpack button label changes back to 'Add to Cart'
    await expect(backpackButton).toHaveText('Add to Cart');

    // Remove second product
    await phoneButton.click();

    // Verify cart badge is empty
    await expect(cartBadge).toHaveText('0');
  });
});
